import{_ as t,c as a,o as r,a5 as o}from"./chunks/framework.CUJoMJm2.js";const b=JSON.parse('{"title":"Protocols","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/index.md","filePath":"protocols/index.md","lastUpdated":1768070912000}'),s={name:"protocols/index.md"};function i(n,e,d,c,l,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="protocols" tabindex="-1">Protocols <a class="header-anchor" href="#protocols" aria-label="Permalink to “Protocols”">​</a></h1><p>Sideband is a layered communication stack for browser-to-daemon communication, designed to work reliably behind NAT with end-to-end encryption.</p><blockquote><p>These specifications are implementation-neutral. You may implement them in any language or runtime, including proprietary systems, under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a> terms.</p></blockquote><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Component</th><th>Purpose</th></tr></thead><tbody><tr><td>App Framing</td><td>SBP</td><td>Framing, multiplexing, message routing</td></tr><tr><td>Relay Session</td><td>SBRP</td><td>Encrypted sessions over relay</td></tr><tr><td>Direct Session</td><td>SBDP</td><td>P2P session (future)</td></tr><tr><td>Semantic</td><td>RPC</td><td>Typed request/response patterns</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>RPC is a semantic layer built on top of SBP message frames, not a transport or session protocol.</p></div><h2 id="sbp-sideband-protocol" tabindex="-1">SBP (Sideband Protocol) <a class="header-anchor" href="#sbp-sideband-protocol" aria-label="Permalink to “SBP (Sideband Protocol)”">​</a></h2><p>Topology-agnostic framing used by all session layers. Defines frame types, message routing, and wire format.</p><p><a href="./sbp/">Read the SBP specification →</a></p><h2 id="sbrp-sideband-relay-protocol" tabindex="-1">SBRP (Sideband Relay Protocol) <a class="header-anchor" href="#sbrp-sideband-relay-protocol" aria-label="Permalink to “SBRP (Sideband Relay Protocol)”">​</a></h2><p>Default transport: secure, relay-based sessions with E2EE. The relay never sees plaintext.</p><p><a href="./sbrp/">Read the SBRP specification →</a></p><h2 id="sbdp-sideband-direct-protocol" tabindex="-1">SBDP (Sideband Direct Protocol) <a class="header-anchor" href="#sbdp-sideband-direct-protocol" aria-label="Permalink to “SBDP (Sideband Direct Protocol)”">​</a></h2><p>Future: direct P2P when both peers can establish a connection without relay.</p><p><a href="./sbdp/">Read the SBDP specification →</a></p><h2 id="rpc" tabindex="-1">RPC <a class="header-anchor" href="#rpc" aria-label="Permalink to “RPC”">​</a></h2><p>Typed request/response/notification semantics inside SBP message frames.</p><p><a href="./rpc/">Read the RPC specification →</a></p>',18)])])}const m=t(s,[["render",i]]);export{b as __pageData,m as default};
